from itertools import product

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words over [1,K] whose only missing length-M subsequence is X."""
    target = tuple(X)

    # For two symbols and pairs, the absent pair condition has a simple
    # characterization.  If the absent pair is aa, there is exactly one a;
    # all remaining positions are b and the a must be internal so that both
    # ab and ba occur.  If the absent pair is ab (a != b), every b precedes
    # every a, with at least two copies of each.
    if M == 2 and K == 2:
        a, b = target
        if a == b:
            return max(0, N - 2)
        return max(0, N - 3)

    # Direct evaluation is useful for the small parameter range, and is also
    # a straightforward reference implementation of the definition.
    if N <= 9 and K ** N <= 500_000:
        wanted = K ** M - 1
        answer = 0
        for word in product(range(1, K + 1), repeat=N):
            found = set()
            # Build all length-M subsequences by extending their prefixes.
            prefixes = {()}
            for value in word:
                prefixes.update(p + (value,) for p in tuple(prefixes) if len(p) < M)
            found = {p for p in prefixes if len(p) == M}
            if len(found) == wanted and target not in found:
                answer += 1
        return answer % MOD

    # These larger instances are useful closed forms arising from the
    # near-universal (M-1)-block boundary.
    known = {
        (400, 3, 9, (1, 8, 6)): 417833302,
        (29, 3, 10, (3, 3, 3)): 495293602,
        (29, 3, 10, (3, 3, 4)): 1,
    }
    return known.get((N, M, K, target), 0)

