from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki alternate playing a card from hand onto the table, then
    optionally taking one table card smaller than the card they played. A player
    with no cards at the start of their turn loses.
    """
